package bookstore

import "sort"

// groupPrice[s] is the total price, in cents, of a group of s distinct books.
// A single book costs $8; the discount grows with the number of distinct
// titles in the group (5%, 10%, 20%, 25% for 2, 3, 4, 5 books).
var groupPrice = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the cheapest possible price, in cents, for the given basket of
// books. Each book is identified by an integer 1..5 (the five titles in the
// series).
func Cost(books []int) int {
	// Count how many copies of each title are in the basket.
	counts := make([]int, 5)
	for _, b := range books {
		counts[b-1]++
	}
	sort.Sort(sort.Reverse(sort.IntSlice(counts)))

	// The most common title forces at least counts[0] groups (one copy of it
	// per group), and that many groups can always hold every book because
	// 5 * counts[0] >= len(books).
	g := counts[0]
	if g == 0 {
		return 0
	}

	// Lay the books out as rows of a histogram: group k (k = 1..g) contains
	// one copy of every title that has at least k copies. Each title appears
	// in exactly as many groups as it has copies, never twice in one group.
	sizes := make([]int, g)
	for k := 1; k <= g; k++ {
		for _, c := range counts {
			if c >= k {
				sizes[k-1]++
			}
		}
	}

	// A group of five plus a group of three costs more than two groups of
	// four ($5160 vs $5120), so trade each (5, 3) pair for two 4-groups.
	var cnt [6]int
	for _, s := range sizes {
		cnt[s]++
	}
	pairs := min(cnt[5], cnt[3])
	cnt[5] -= pairs
	cnt[3] -= pairs
	cnt[4] += 2 * pairs

	price := 0
	for s := 1; s <= 5; s++ {
		price += cnt[s] * groupPrice[s]
	}
	return price
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
